/** Text colours that read well on the backdrop (same roles as a Palette). */
export type BackdropColors = {
  ink: string;
  accent: string;
  onAccent: string;
  sparkle: string;
};

export type Backdrop = {
  id: BackdropId;
  tr: string;
  en: string;
  /** Full-size image (Metro asset module). */
  image: number;
  /** 270 x 480 thumbnail for pickers. */
  thumb: number;
  dark: boolean;
  colors: BackdropColors;
};

