export function backdropById(id: BackdropId): Backdrop {
  return BACKDROPS.find((b) => b.id === id) ?? BACKDROPS[0];
}

/** A backdrop that suits each product category by default. */
export const CATEGORY_BACKDROP: Record<string, BackdropId> = {
  cosmetics: "marble-white",
  jewellery: "marble-black",
  fashion: "paper-sand",
  home: "oak",
  food: "walnut",
  electronics: "concrete",
};

/**
 * The look a new video starts on while the user has not picked one:
 * "backdrop" uses CATEGORY_BACKDROP for the category, "palette" the
 * category's plain colours (as before backdrops existed).
 */
export const DEFAULT_BACKGROUND: "backdrop" | "palette" = "backdrop";

/** Local file URIs of the bundled images, resolved once per launch. */
const resolved = new Map<BackdropId, Promise<string>>();

/**
 * A local file URI for the backdrop image, for the native renderer. The URI
 * can change between launches, so drafts store the id and resolve it again.
 */
export function backdropUri(id: BackdropId): Promise<string> {
  let uri = resolved.get(id);
  if (!uri) {
    uri = Asset.fromModule(backdropById(id).image)
      .downloadAsync()
      .then((asset) => asset.localUri ?? asset.uri);
    uri.catch(() => resolved.delete(id));
    resolved.set(id, uri);
  }
  return uri;
}

/**
 * The scene for a bundled backdrop: the whole 9:16 image, no darkening, and
 * the product where `productPlacement` puts a cut-out of this pixel size.
 * One helper for the editor and the posters, so both draw the same thing.
 */
export async function backdropScene(
  id: BackdropId,
  cutoutWidth: number,
  cutoutHeight: number,
): Promise<SceneInput> {
  return {
    uri: await backdropUri(id),
    crop: { x: 0, width: 1 },
    productRect: productPlacement(cutoutWidth, cutoutHeight),
    shade: 0,
  };
}
